WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT id, event_type, page, event_time, duration_sec, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, event_type, event_time, session_no FROM sessions_web_events ORDER BY id DESC
